(function(){
var GSP='https://www.greenescholars.org/',IA='https://intuition-ai.surge.sh/',LI='https://www.linkedin.com/in/jordan-johnsson-b11966408/';
var FRIENDS=[['Liam','humble, respectful, determined'],['Maeve','devoted, caring, dependable'],['Ela','funny, proud, patient'],['Phevos','outgoing, honest, genuine'],['Elizer','kind, respectful, caring'],['Shanley','infectious, smile, athletic, determined'],['Giselle','funny, confident, empathetic'],['Adrien','good man, somebody to compete with, reliable']];
function linkGsp(){var root=document.querySelector('main');if(!root)return;var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:function(n){if(!/Greene Scholars|GSP/.test(n.nodeValue))return 2;var p=n.parentNode;if(p.closest('a,script,style,button,.gsp-link'))return 2;return 1}});var list=[],n;while(n=w.nextNode())list.push(n);list.forEach(function(t){var parts=t.nodeValue.split(/(Greene Scholars Program|Greene Scholars|GSP)/);var f=document.createDocumentFragment();parts.forEach(function(s,i){if(i%2){var a=document.createElement('a');a.className='gsp-link';a.href=GSP;a.target='_blank';a.rel='noopener noreferrer';a.textContent=s;f.appendChild(a)}else if(s)f.appendChild(document.createTextNode(s))});t.parentNode.replaceChild(f,t)})}
function iaCard(){var h=[].slice.call(document.querySelectorAll('#stem article h3')).find(function(x){return /Intuition AI/i.test(x.textContent)});if(!h)return;var art=h.closest('article');if(art.classList.contains('ia-card'))return;art.classList.add('ia-card');art.setAttribute('role','link');art.setAttribute('tabindex','0');function go(){window.open(IA,'_blank','noopener')}art.addEventListener('click',function(e){if(e.target.closest('a'))return;go()});art.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.target.closest('a'))go()})}
function linkedin(){document.querySelectorAll('.hero-links,#contact [class*="gap"]').forEach(function(box){if(box.querySelector('.li-link'))return;var ref=box.querySelector('a[href*="instagram"]');if(!ref)return;var a=ref.cloneNode(false);a.className=(ref.className||'').replace(/cicon-\w+/,'')+' li-link';a.href=LI;a.setAttribute('aria-label','LinkedIn');a.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" width="19" height="19" viewBox="0 0 24 24" fill="currentColor"><path d="M20.45 20.45h-3.56v-5.57c0-1.33-.03-3.04-1.85-3.04-1.86 0-2.14 1.45-2.14 2.94v5.67H9.35V9h3.41v1.56h.05c.48-.9 1.64-1.85 3.37-1.85 3.6 0 4.27 2.37 4.27 5.46v6.28zM5.34 7.43a2.06 2.06 0 1 1 0-4.12 2.06 2.06 0 0 1 0 4.12zM7.12 20.45H3.56V9h3.56v11.45z"/></svg>';ref.parentNode.insertBefore(a,ref)})}
function friends(){if(document.getElementById('friends'))return;var tr=document.getElementById('track');if(!tr)return;var s=document.createElement('section');s.id='friends';s.setAttribute('aria-label','Three words from friends');var h='<div class="fw-wrap"><h2 class="hero-heading">In three words</h2><p class="fw-sub">I asked friends to describe me in three words.</p><div class="fw-grid">';FRIENDS.forEach(function(f){h+='<div class="fw-card"><div class="fw-name">'+f[0]+'</div><p class="fw-words">'+f[1]+'</p></div>'});s.innerHTML=h+'</div></div>';tr.parentNode.insertBefore(s,tr)}
function langText(){document.querySelectorAll('#language h3').forEach(function(h){if(h.textContent.trim()==='Lessons and home life')h.textContent='German'});document.querySelectorAll('#language p').forEach(function(p){if(/alongside German and English/.test(p.textContent)){p.textContent=p.textContent.replace(/ alongside German and English/,' alongside German')}});var w=document.createTreeWalker(document.getElementById('language')||document.body,NodeFilter.SHOW_TEXT),n,L=[];while((n=w.nextNode()))L.push(n);L.forEach(function(t){var v=t.nodeValue;if(/German lessons since first grade/.test(v))t.nodeValue=v.replace('German lessons since first grade','German since preschool');else if(v.trim()==='Since 1st grade')t.nodeValue=v.replace('Since 1st grade','Since preschool')})}
function tag(){document.querySelectorAll('.hero-overlay p').forEach(function(p){var w=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),n;while(n=w.nextNode()){if(/Musician\. Builder\./.test(n.nodeValue))n.nodeValue=n.nodeValue.replace('Musician. Builder.','Musician. Hardware and Software Engineer.')}var a=p.getAttribute('aria-label');if(a&&/Builder\./.test(a))p.setAttribute('aria-label',a.replace('Musician. Builder.','Musician. Hardware and Software Engineer.'))})}
function run(){try{tag();linkGsp();iaCard();linkedin();friends();langText()}catch(e){}}
var t;new MutationObserver(function(){clearTimeout(t);t=setTimeout(run,150)}).observe(document.documentElement,{childList:true,subtree:true});
document.addEventListener('DOMContentLoaded',run);setTimeout(run,1500);setTimeout(run,4000);
})();
;(function(){function fit(){document.querySelectorAll('.family-carousel').forEach(function(c){var cs=c.querySelectorAll('.family-card'),st=c.querySelector('.family-stage');if(!st||!cs.length)return;var m=0;cs.forEach(function(k){k.style.setProperty('height','auto','important');m=Math.max(m,k.offsetHeight)});m=Math.ceil(m)+2;cs.forEach(function(k){k.style.setProperty('height',m+'px','important')});st.style.setProperty('height',(m+40)+'px','important')})}var t;function s(){clearTimeout(t);t=setTimeout(fit,120)}window.addEventListener('resize',s);document.addEventListener('DOMContentLoaded',s);[500,1500,3000,5000].forEach(function(d){setTimeout(fit,d)});if(document.fonts&&document.fonts.ready)document.fonts.ready.then(s)})();
